export XZ_WS_URL='wss://api.tenclass.net/xiaozhi/v1/' XZ_BARGE_ANY=0
# 小智本地唤醒脚本：公共会话锁、独立 processed PCM 订阅、定向事件。
# 官方“小爱同学”由固件接管：先收净本会话，再交给官方。
# 所有本地词命中后都先结束当前会话，再重连对应路径，包括同名词。
# WEBD-UNINSTALL-TIMEOUT: 30
XZ_CLIENT_SHA256='4d5adb38e8cec26f0f8abcb09a463688fa7d08c583fc7b74e96d4ef312291952'
BASE=/data/lx06/xiaozhi
SETTINGS=/usr/lib/lx06/script-settings
BIN=$BASE/xz_client_armhf
XA=/usr/lib/lx06/xiaoai
LOG=/data/lx06/logs/xiaozhi.watch.log
logfile=$LOG
ENVF=$BASE/xz.env
TRIGCONF=$BASE/trig.conf
WWEV=/tmp/lx06-wake-xz_watch.sh.event
SPID=
say(){ printf 'XZ-DEPLOY %s\n' "$*"; }
log(){ mkdir -p /data/lx06/logs; _s=$(wc -c 2>/dev/null < "$LOG"); case "$_s" in ''|*[!0-9]*) _s=0;; esac; [ "$_s" -gt 60000 ] && mv -f "$LOG" "$LOG.1"; echo "$(date) $*" >> "$LOG"; }
sha_of(){ sha256sum "$1" 2>/dev/null | awk '{print $1}'; }
if [ "${1:-}" = --uninstall ]; then
  "$SETTINGS" forget "$0" || exit 2
  # Keeper stops this script's complete tree before invoking uninstall.
  rm -rf "$BASE"
  rm -f "$LOG" "$LOG.1" /data/lx06/logs/xiaozhi.talk.log "$WWEV"
  rm -f /tmp/lx06-xz-timeline.log /tmp/lx06-xz-timeline.log.previous /tmp/lx06-xz-resident.lock
  for lock in /tmp/lx06-mic/xz-*.lock; do
    [ -f "$lock" ] && [ ! -L "$lock" ] || continue
    ( flock -n 9 && rm -f "$lock" ) 9<"$lock"
  done
  printf 'XZ-UNINSTALL-DONE\n'
  exit 0
fi
[ "$(id -u)" = 0 ] || { say '需要 root 运行'; exit 2; }

# Embedded in xz_watch.sh by build_xz_pause_update.py.
if [ "${1:-}" = --mcp-task-session ] || [ "${1:-}" = --mcp-task-state ]; then
  task_root=/tmp/lx06-xz-mcp-task
  current=$(readlink "$task_root/active") || exit 1
  case "$current" in session.[A-Za-z0-9][A-Za-z0-9][A-Za-z0-9][A-Za-z0-9][A-Za-z0-9][A-Za-z0-9]) ;; *) exit 1;; esac
  [ -d "$task_root/$current" ] || exit 1
  if [ "$1" = --mcp-task-session ]; then
    [ "$#" -eq 1 ] || exit 2
    printf '%s\n' "$current"
    exit
  fi
  [ "$#" -eq 4 ] || [ "$#" -eq 5 ] || exit 2
  [ "$current" = "$2" ] || exit 1
  task_id=$3
  task_state=$4
  task_query=${5:-}
  case "$task_id" in ''|*[!a-zA-Z0-9_-]*) exit 2;; esac
  [ "${#task_id}" -le 48 ] || exit 2
  case "$task_state" in running|ready|queried) ;; *) exit 2;; esac
  if [ "$#" -eq 5 ]; then
    export LC_ALL=C
    [ -n "$task_query" ] && [ "${#task_query}" -le 160 ] || exit 2
    [ "$(printf '%s' "$task_query" | tr -d '[:cntrl:]')" = "$task_query" ] || exit 2
  fi
  session_dir=$task_root/$current
  state_file=$session_dir/$task_id.state
  umask 077
  (
    flock -x 9 || exit 1
    [ "$(readlink "$task_root/active")" = "$current" ] || exit 1
    now=$(date +%s) || exit 1
    active=0
    retained=0
    for item in "$session_dir"/*.state; do
      [ -f "$item" ] || continue
      written=$(date -r "$item" +%s) || exit 1
      if [ "$((now - written))" -gt 90 ]; then
        rm -f "$item" || exit 1
        continue
      fi
      read -r version old_id old_state < "$item" || exit 1
      retained=$((retained + 1))
      [ "$old_state" = queried ] || active=$((active + 1))
    done
    if [ -f "$state_file" ]; then
      {
        read -r version old_id old_state || exit 1
        [ "$old_id" = "$task_id" ] || exit 1
        case "$old_state:$task_state" in
          queried:queried) exit 0;;
          queried:*|ready:running) exit 1;;
        esac
        if [ "$version" = v2 ] && [ -z "$task_query" ]; then
          IFS= read -r task_query || exit 1
        fi
      } < "$state_file"
    else
      [ "$task_state" != queried ] || exit 0
      [ "$active" -lt 8 ] && [ "$retained" -lt 32 ] || exit 75
    fi
    draft=$(mktemp "$task_root/.task.XXXXXX") || exit 1
    trap 'rm -f "$draft"' EXIT
    if [ -n "$task_query" ]; then
      printf 'v2 %s %s\n%s\n' "$task_id" "$task_state" "$task_query" > "$draft" || exit 1
    else
      printf 'v1 %s %s\n' "$task_id" "$task_state" > "$draft" || exit 1
    fi
    mv -f "$draft" "$state_file"
  ) 9>> "$session_dir/lock"
  exit $?
fi

syslib_ok(){
  [ -f /usr/lib/libssl.so.1.0.0 ] || return 1
  [ -f /usr/lib/libcrypto.so.1.0.0 ] || return 1
  [ -f /usr/lib/libopus.so.0 ] || return 1
  return 0
}
bin_ok(){
  [ -x "$BIN" ] || return 1
  [ "$(sha_of "$BIN")" = "$XZ_CLIENT_SHA256" ] || return 1
  syslib_ok || return 1
  return 0
}
drop_dup_libs(){
  [ -d "$BASE/lib" ] || return 0
  _n=$(du -k "$BASE/lib" 2>/dev/null | awk 'END{print $1}')
  rm -rf "$BASE/lib"
  log "DROP duplicate libs dir=$BASE/lib was=${_n:-?}KB now=/usr/lib"
}
